CREATE TABLE IF NOT EXISTS modulos_aplicacion(mod_id BIGSERIAL PRIMARY KEY,mod_cod VARCHAR(50) NOT NULL UNIQUE,mod_tit VARCHAR(100) NOT NULL,mod_des VARCHAR(250) NOT NULL,mod_rut VARCHAR(100) NOT NULL UNIQUE,mod_pos INTEGER NOT NULL,mod_usu_mov VARCHAR(100) NOT NULL,mod_fec_mov TIMESTAMP NOT NULL,mod_act BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS empresas_modulos(emm_id BIGSERIAL PRIMARY KEY,emp_id BIGINT NOT NULL,mod_id BIGINT NOT NULL REFERENCES modulos_aplicacion(mod_id),emm_dis BOOLEAN NOT NULL DEFAULT TRUE,emm_pos INTEGER NOT NULL,UNIQUE(emp_id,mod_id));
INSERT INTO modulos_aplicacion(mod_cod,mod_tit,mod_des,mod_rut,mod_pos,mod_usu_mov,mod_fec_mov,mod_act) VALUES
('ADMINISTRACION','Administración','Empresas, usuarios, perfiles y configuración.','administracion',1,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('COMUNICACIONES','Comunicaciones','Bandeja, conversaciones y atención omnicanal.','comunicaciones',2,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('TERRITORIO','Territorio','Domicilios y estructura territorial.','territorio',3,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('PERSONAS','Personas','Personas, representantes y datos relacionados.','personas',4,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('CLIENTES','Clientes','Gestión de clientes.','clientes',5,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('EMPLEADOS','Empleados','Gestión de empleados.','empleados',6,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('PRODUCTOS','Productos','Catálogo y gestión de productos.','productos',7,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('SERVICIOS','Servicios','Catálogo, duración y gestión de servicios.','servicios',8,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('COMPRAS','Compras','Compras y relación con proveedores.','compras',9,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('VENTAS','Ventas','Operaciones comerciales y detalle de ventas.','ventas',10,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('RECURSOS','Recursos','Empleados, maquinaria y capacidades operativas.','recursos',11,'SISTEMA',CURRENT_TIMESTAMP,TRUE),('CAJA','Caja','Aperturas, cierres y movimientos de caja.','caja',12,'SISTEMA',CURRENT_TIMESTAMP,TRUE) ON CONFLICT(mod_cod) DO NOTHING;
INSERT INTO empresas_modulos(emp_id,mod_id,emm_dis,emm_pos) SELECT e.emp_id,m.mod_id,TRUE,m.mod_pos FROM empresas e CROSS JOIN modulos_aplicacion m ON CONFLICT(emp_id,mod_id) DO NOTHING;
INSERT INTO parametros(emp_id,par_cod,par_des,par_val,par_mod,par_usu_mov,par_fec_mov,par_act)
SELECT e.emp_id,'RUTA_DOCUMENTOS_MODULOS','Ruta de imágenes y documentos de módulos','C:\Workspace\Documentos\Empresa '||e.emp_id||'\Modulos','ADMINISTRACION','SISTEMA',CURRENT_TIMESTAMP,TRUE
FROM empresas e ON CONFLICT(emp_id,par_mod,par_cod) DO NOTHING;
